package io.github.leetcode.strings;

public class CheckIfTheSentenceIsPangram {

    public boolean checkIfPangram(String sentence) {
        int[] chars = new int[26];
        int n = sentence.length();

        if(n < 26){
            return false;
        }

        int count = 0;

        for(int i = 0; i < n; i++){
            chars[sentence.charAt(i) - 'a']++;
            if(chars[sentence.charAt(i) - 'a'] == 1){
                count++;
            }
        }

        return count == 26;
    }

}

class Solution {
public:
    bool checkIfPangram(string sentence) {
        // We iterate over 'sentence' for 26 times, one for each letter 'currChar'.
        for (int i = 0; i < 26; ++i) {
            char currChar = 'a' + i;

            // If 'sentence' doesn't contain currChar, it is not a pangram.
            if (sentence.find(currChar) == string::npos)
                return false;
        }

        // If we manage to find all 26 letters, it is a pangram.
        return true;
    }
};

