class Solution {
public:
    bool checkIfPangram(string sentence) {
        int seen=0;
        for(auto it:sentence)
        {
            int curr=it-'a';
            int val=1<<curr;
            seen|=val;
        }
        return seen==(1<<26)-1;
    }
};

